\o /dev/null
create function pg_temp.check_true(condition boolean, message text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'Assertion failed: %', message; end if; end $$;
create function pg_temp.expect_error(statement text, expected_state text) returns void language plpgsql as $$
declare actual_state text;
begin
  begin execute statement; exception when others then get stacked diagnostics actual_state = returned_sqlstate; end;
  if actual_state is distinct from expected_state then raise exception 'Expected %, received % for %', expected_state, actual_state, statement; end if;
end $$;
select pg_temp.check_true((select count(*) from public.households) = 2, 'original household archives are retained');
select pg_temp.check_true((select cookbook_private.snapshot()->'state') = (select state from public.households where name = 'Our kitchen'), 'migration preserves the full document exactly');
select pg_temp.check_true((select household_id from public.cookbook_meta) = (select id from public.households where name = 'Our kitchen'), 'existing photo and Reminders namespace is retained');
select pg_temp.check_true((select revision from public.cookbook_meta) = 7, 'migration preserves the revision');
select pg_temp.check_true((select count(*) from public.cookbook_records) = 3, 'records are stored separately');
set role anon;
select pg_temp.expect_error('select public.read_cookbook()','42501');
select pg_temp.expect_error('select public.cookbook_info()','42501');
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''grocery'',true,''anonymous-1'',7)','42501');
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-4000-8000-000000000004';
select pg_temp.expect_error('select public.read_cookbook()','42501');
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''grocery'',true,''unconfirmed-1'',7)','42501');
set request.jwt.claim.sub = '00000000-0000-4000-8000-000000000001';
select set_config('test.cookbook',public.cookbook_info()->>'householdId',false);
select pg_temp.check_true(public.read_cookbook(7)->>'unchanged' = 'true', 'unchanged refresh returns no cookbook payload');
select pg_temp.check_true(not (public.read_cookbook(7) ? 'state'), 'unchanged refresh is small');
select pg_temp.expect_error('select * from public.cookbook_records','42501');
select pg_temp.expect_error('select * from public.cookbook_meta','42501');
select pg_temp.expect_error('select * from public.households','42501');
select pg_temp.expect_error('select public.create_household(''A different cookbook'')','42501');
select pg_temp.expect_error('select public.invite_to_household(''someone@example.test'')','42501');
select pg_temp.expect_error('select public.write_cookbook_patch(current_setting(''test.cookbook'')::uuid,7,''{}'')','42501');
select set_config('test.recipe', (public.read_cookbook()->'state'->'recipes')::text,false);
select public.set_cookbook_flag('shopping.toggle','grocery',true,'shared-check-1',7) as checked_result \gset
select pg_temp.check_true((:'checked_result'::jsonb)->>'revision' = '8', 'flag save advances one revision');
select pg_temp.check_true(not (:'checked_result'::jsonb ? 'state') and octet_length(:'checked_result') < 1000, 'flag save returns only its changed record');
select pg_temp.check_true(public.read_cookbook()->'state'->'shopping'->0->>'checked' = 'true', 'checkmark saved');
select pg_temp.check_true((public.read_cookbook()->'state'->'recipes')::text = current_setting('test.recipe'), 'checking a grocery preserves recipes');
select public.set_cookbook_flag('shopping.toggle','grocery',true,'shared-check-1',7);
select pg_temp.check_true(public.cookbook_info()->>'revision' = '8', 'retry does not apply twice');
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''grocery'',false,''shared-stale-1'',7)','40001');
-- A confirmed account with no legacy household sees and edits the same cookbook.
set request.jwt.claim.sub = '00000000-0000-4000-8000-000000000003';
select pg_temp.check_true(public.cookbook_info()->>'householdId' = current_setting('test.cookbook'), 'new account opens the universal cookbook');
select pg_temp.check_true(public.read_cookbook()->'state'->'recipes'->0->>'notes' = 'Original notes', 'new account reads existing recipes');
select public.set_cookbook_flag('shopping.toggle','grocery',false,'second-user-check',8);
select pg_temp.check_true(public.cookbook_info()->>'revision' = '9', 'another account can save to the same cookbook');
select public.set_cookbook_flag('recipe.favorite','rice',true,'shared-favorite-1',9,'2026-11-01T00:00:00.000Z');
select pg_temp.check_true(public.read_cookbook()->'state'->'recipes'->0->>'favorite' = 'true', 'favorite saved without replacing recipe');
select pg_temp.check_true(public.read_cookbook()->'state'->'recipes'->0->>'notes' = 'Original notes', 'favorite preserves unrelated fields');
select pg_temp.expect_error('select public.set_cookbook_flag(''recipe.favorite'',''rice'',false,''stale-recipe-1'',10,''old'')','40001');
select pg_temp.expect_error('select public.set_cookbook_flag(''settings.save'',''rice'',false,''invalid-type-1'',10)','22023');
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''missing'',false,''missing-row-1'',10)','P0002');
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''grocery'',null,''invalid-bool-1'',10)','22023');
reset role;
select set_config('test.recipe_xmin',xmin::text,false) from public.cookbook_records where collection = 'recipes' and id = 'rice';
set role service_role;
select pg_temp.expect_error('update public.households set revision = revision + 1','40001');
select pg_temp.check_true(public.cookbook_sync_allowed(current_setting('test.cookbook')::uuid,'00000000-0000-4000-8000-000000000003'), 'new confirmed account can use native grocery sync');
select pg_temp.check_true(not public.cookbook_sync_allowed(current_setting('test.cookbook')::uuid,'00000000-0000-4000-8000-000000000004'), 'unconfirmed account cannot use a signed old handoff');
select pg_temp.check_true(public.read_cookbook()->>'revision' = '10', 'server can read the shared snapshot');
select public.write_cookbook_patch(current_setting('test.cookbook')::uuid,10,'{"collections":{"pantry":{"upsert":[{"id":"stock","name":"rice","amount":500,"unit":"g","location":"Pantry","note":"New package"}],"remove":[]}},"values":{},"appendOperations":["pantry-delta-1"]}');
select pg_temp.check_true(public.read_cookbook()->'state'->'pantry'->0->>'amount' = '500', 'server patch changes one record');
select pg_temp.check_true(public.write_cookbook_patch(current_setting('test.cookbook')::uuid,10,'{}') is null, 'stale server patch is rejected');
select pg_temp.expect_error('select public.write_cookbook_patch(current_setting(''test.cookbook'')::uuid,11,''{"collections":{"pantry":{"upsert":[{"id":"new-row","name":"Should roll back"}],"remove":[],"order":["missing"]}},"values":{},"appendOperations":[]}'')','P0001');
select pg_temp.check_true(jsonb_array_length(public.read_cookbook()->'state'->'pantry') = 1, 'invalid patch rolls back all rows');
select pg_temp.check_true(public.cookbook_info()->>'revision' = '11', 'invalid patch leaves revision unchanged');
reset role;
select pg_temp.check_true((select xmin::text from public.cookbook_records where collection = 'recipes' and id = 'rice') = current_setting('test.recipe_xmin'), 'pantry save does not rewrite recipe rows');
update public.cookbook_records set data = jsonb_set(data,'{addedToPantry}','true') where collection = 'shopping' and id = 'grocery';
set role authenticated;
set request.jwt.claim.sub = '00000000-0000-4000-8000-000000000001';
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''grocery'',false,''purchased-row-1'',11)','22023');
reset role;
select pg_temp.check_true((select public from storage.buckets where id = 'cookbook-photos') = false, 'photos remain private');
-- Direct database fast paths retain session/account revocation checks.
update auth.users set banned_until = now() + interval '1 hour' where id = '00000000-0000-4000-8000-000000000001';
set role authenticated;
select pg_temp.expect_error('select public.read_cookbook()','42501');
select pg_temp.expect_error('select public.set_cookbook_flag(''shopping.toggle'',''grocery'',false,''banned-user-1'',11)','42501');
reset role;
update auth.users set banned_until = null where id = '00000000-0000-4000-8000-000000000001';
update auth.sessions set not_after = now() - interval '1 minute' where user_id = '00000000-0000-4000-8000-000000000001';
set role authenticated;
select pg_temp.expect_error('select public.read_cookbook()','42501');
reset role;
update auth.sessions set not_after = null where user_id = '00000000-0000-4000-8000-000000000001';
set role authenticated;
set request.jwt.claim.session_id = '00000000-0000-4000-8000-000000000003';
select pg_temp.expect_error('select public.read_cookbook()','42501');
set request.jwt.claim.session_id = '';
reset role;
delete from auth.sessions where user_id = '00000000-0000-4000-8000-000000000001';
set role authenticated;
select pg_temp.expect_error('select public.read_cookbook()','42501');
reset role;
-- New-row insertion, ordering, deletion and metadata edits exercise the same
-- patch shapes used by recipe/pantry/shopping forms and cooking commands.
set role service_role;
select public.write_cookbook_patch(current_setting('test.cookbook')::uuid,11,'{"collections":{"pantry":{"upsert":[{"id":"salt","name":"salt","amount":1,"unit":"tsp","location":"Pantry","note":""}],"remove":[],"order":["salt","stock"]}},"values":{"shoppingWeek":"2026-11-02"},"appendOperations":["ordered-add-1"]}');
select pg_temp.check_true(public.read_cookbook()->'state'->'pantry'->0->>'id' = 'salt', 'new records can be ordered before existing records');
select pg_temp.check_true(public.read_cookbook()->'state'->'pantry'->1->>'id' = 'stock', 'reordering retains existing data');
select pg_temp.check_true(public.read_cookbook()->'state'->>'shoppingWeek' = '2026-11-02', 'metadata is patched with records atomically');
select public.write_cookbook_patch(current_setting('test.cookbook')::uuid,12,'{"collections":{"pantry":{"upsert":[],"remove":["salt"],"order":["stock"]}},"values":{"settings":{"servings":4,"weekStartsOn":1,"autoLeftovers":true,"categories":["Mains"]}},"appendOperations":["ordered-delete-1"]}');
select pg_temp.check_true(jsonb_array_length(public.read_cookbook()->'state'->'pantry') = 1 and public.read_cookbook()->'state'->'pantry'->0->>'id' = 'stock', 'deleting one record retains the other');
select pg_temp.check_true(public.read_cookbook()->'state'->'settings'->>'servings' = '4', 'settings edits are preserved');
reset role;
